root, sandbox, junit = map(Path, sys.argv[1:4])
sys.path[:0] = [str(root), str(root / '.venv/Lib/site-packages')]
allowed_read = [os.path.normcase(os.path.abspath(p)) for p in (root, sandbox, Path(sys.base_prefix))]
safe_root = os.path.normcase(os.path.abspath(sandbox))
xml_path = os.path.normcase(os.path.abspath(junit))
