class IsolationViolation(BaseException):
    pass
def within(path, base):
    return path == base or path.startswith(base + os.sep)
def check_path(value, writing=False):
    if value is None or isinstance(value, int):
        return
    path = os.path.normcase(os.path.abspath(os.fsdecode(value)))
    if path == os.path.normcase(os.devnull):
        return
    if writing:
        safe = within(path, safe_root) or path == xml_path
    else:
        safe = any(within(path, base) for base in allowed_read)
        name = os.path.basename(path)
        if (name == '.env' or name.startswith('.env.')) and not within(path, safe_root):
            safe = False
    if not safe:
        violations.append('filesystem-write' if writing else 'filesystem-read')
