        violations.append(event)
        raise IsolationViolation('forbidden external operation: ' + event)
    if event == 'import' and args[0].startswith('desktop'):
        violations.append('desktop-import')
        raise IsolationViolation('desktop launcher is out of scope')
    if event == 'open':
        flags = args[2] or 0
        check_path(args[0], bool(flags & (os.O_WRONLY | os.O_RDWR | os.O_CREAT | os.O_TRUNC | os.O_APPEND)))
    elif event in {'os.listdir', 'os.scandir'}:
        check_path(args[0] if args else os.getcwd())
    elif event in {'os.mkdir', 'os.remove', 'os.rmdir', 'os.chmod'}:
        check_path(args[0], True)
    elif event in {'os.rename', 'os.link', 'os.symlink'}:
        check_path(args[0], True)
        check_path(args[1], True)
    elif event == 'sqlite3.connect' and args[0] != ':memory:':
        check_path(args[0], True)
